REPLACE INTO `ai_report_wsh` (`id_wsh`, `order_id_wsh`, `pet_id_wsh`, `keeper_id_wsh`, `content_wsh`, `type_wsh`, `deleted_wsh`, `created_at_wsh`) VALUES (1, 1, 1, 1, '# Daily Care Report\n\n**Pet**: Fluffy\n**Date**: 2024-01-02\n\n## Feeding\n- Morning: 150g fish cat food\n- Water intake: Normal\n\n## Activity\n- Played with feather wand for 20min\n- Slept on cat tower\n\n## Health\n- Temperature: 38.5Â°C\n- Mood: Happy and relaxed\n\n## Notes\nFluffy is adjusting well. She enjoys sunny spots near the window.', 'daily_care', 0, '2026-06-24 03:46:43');
REPLACE INTO `ai_report_wsh` (`id_wsh`, `order_id_wsh`, `pet_id_wsh`, `keeper_id_wsh`, `content_wsh`, `type_wsh`, `deleted_wsh`, `created_at_wsh`) VALUES (2, 101, 101, 101, '# Final Boarding Summary\n\n**Pet**: Max\n**Period**: Jan 1-3, 2025\n\n## Overall\nMax had a wonderful stay. He was energetic and playful throughout.\n\n## Diet\n- Ate all meals (chicken-free per owner request)\n- Took treats happily\n\n## Exercise\n- Daily walks in the park (40min each)\n- Played fetch daily\n\n## Health\n- No issues observed\n- Medications administered on time\n\n## Recommendation\nMax is a healthy, well-trained dog. Would love to host him again!', 'final_report', 0, '2026-06-24 03:46:43');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (1, 'Boarding Guide', '1. Ensure pets are healthy before boarding\n2. Provide pet regular food\n3. Daily activity at least 2 hours\n4. Notify owner of issues immediately', 'boarding', 'txt', NULL, 120, 0, '2026-06-22 13:11:08', '2026-06-22 13:11:08');
