REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (1, 'Boarding Guide', '1. Ensure pets are healthy before boarding\n2. Provide pet regular food\n3. Daily activity at least 2 hours\n4. Notify owner of issues immediately', 'boarding', 'txt', NULL, 120, 0, '2026-06-23 00:33:36', '2026-06-23 00:33:36');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (2, 'Refund Policy', '1. Full refund within 24h\n2. 3 days before: 10% fee\n3. 1 day before: 30% fee\n4. No refund after start', 'refund', 'txt', NULL, 90, 0, '2026-06-23 00:33:36', '2026-06-23 00:33:36');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (3, 'Complaint Rules', '1. File within 7 days after service\n2. Provide evidence\n3. Processed in 3-5 business days', 'complaint', 'txt', NULL, 70, 0, '2026-06-23 00:33:36', '2026-06-23 00:33:36');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (4, 'Care Guide', '1. Feed on schedule\n2. Fresh water always\n3. Walk dogs twice daily\n4. Monitor health daily', 'care', 'txt', NULL, 60, 0, '2026-06-23 00:33:36', '2026-06-23 00:33:36');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (5, 'Vaccine Requirements', '1. Core vaccines required\n2. Dogs: Rabies, Distemper, Parvo\n3. Cats: Rabies, FVRCP', 'vaccine', 'txt', NULL, 80, 0, '2026-06-23 00:33:36', '2026-06-23 00:33:36');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (1, '宠物寄养规则', '1. 寄养前需确保宠物已完成疫苗接种\n2. 寄养期间宠物主需提供宠物食物\n3. 寄养员需每日提供宠物活动时间不少于2小时\n4. 寄养期间如宠物生病需及时通知宠物主\n5. 寄养期间宠物意外伤害由寄养员负责\n6. 寄养期间宠物死亡由寄养员全责赔偿\n7. 寄养前需签订寄养协议\n8. 寄养费用按天计算，不足一天按一天计算', 'boarding', 'txt', NULL, 0, 0, '2026-06-23 00:41:19', '2026-06-23 00:41:19');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (2, '退款规则', '1. 订单支付后24小时内可全额退款\n2. 寄养开始前3天退款扣除10%手续费\n3. 寄养开始前1天退款扣除30%手续费\n4. 寄养开始后不接受退款\n5. 因平台原因导致无法服务的，全额退款\n6. 因商家原因取消订单的，全额退款并赔偿20%\n7. 退款到账时间：1-3个工作日\n8. 部分退款按实际未服务天数计算', 'refund', 'txt', NULL, 0, 0, '2026-06-23 00:41:19', '2026-06-23 00:41:19');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (3, '投诉规则', '1. 投诉需在服务结束后7天内提出\n2. 投诉需要提供相关证据（照片/视频）\n3. 平台客服将在24小时内受理投诉\n4. 投诉处理周期为3-5个工作日\n5. 严重投诉升级至平台管理员处理\n6. 恶意投诉将影响用户信用分\n7. 投诉处理结果将以站内信形式通知\n8. 对处理结果不满可再次申诉', 'complaint', 'txt', NULL, 0, 0, '2026-06-23 00:41:19', '2026-06-23 00:41:19');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (4, '宠物护理指南', '1. 每日定时喂食，保持饮食规律\n2. 提供充足的饮用水\n3. 每日遛狗不少于2次\n4. 保持居住环境清洁卫生\n5. 定期梳毛，防止打结\n6. 注意观察宠物精神状态\n7. 发现异常及时记录并通知主人\n8. 按主人要求给药（如有）', 'care', 'txt', NULL, 0, 0, '2026-06-23 00:41:19', '2026-06-23 00:41:19');
REPLACE INTO `knowledge_document_wsh` (`id_wsh`, `title_wsh`, `content_wsh`, `category_wsh`, `source_type_wsh`, `source_path_wsh`, `word_count_wsh`, `deleted_wsh`, `created_at_wsh`, `updated_at_wsh`) VALUES (5, '疫苗要求', '1. 寄养宠物必须完成核心疫苗接种\n2. 犬类：狂犬病疫苗、犬瘟热疫苗、细小病毒疫苗\n3. 猫类：狂犬病疫苗、猫三联疫苗\n4. 疫苗需在有效期内\n5. 需提供疫苗接种证明\n6. 未接种疫苗的宠物需加收健康管理费\n7. 建议接种流感疫苗（季节性）\n8. 老年宠物建议做健康检查', 'vaccine', 'txt', NULL, 0, 0, '2026-06-23 00:41:19', '2026-06-23 00:41:19');
